import { test, expect } from '@playwright/test';

test('has title and heading', async ({ page }) => {
  await page.goto('/');
  await expect(page).toHaveTitle(/QA Practice Shop/);
  await expect(page.getByRole('heading', { name: 'QA Practice Shop' })).toBeVisible();
});

test('navigates to the login page', async ({ page }) => {
  await page.goto('/');
  await page.getByRole('navigation', { name: 'Main' }).getByRole('link', { name: 'Login' }).click();
  await expect(page).toHaveURL(/\/login$/);
});
